def separate_paren_groups(paren_string: str) -> list[str]:
    cleaned = paren_string.replace(' ', '')
    result = []
    depth = 0
    start = 0
    for i, ch in enumerate(cleaned):
        if ch == '(':
            if depth == 0:
                start = i
            depth += 1
        elif ch == ')':
            depth -= 1
            if depth < 0:
                raise ValueError("Unmatched closing parenthesis")
            if depth == 0:
                result.append(cleaned[start:i+1])
        else:
            # invalid character
            raise ValueError(f"Invalid character '{ch}' in input")
    if depth != 0:
        raise ValueError("Unmatched opening parenthesis")
    return result

def truncate_number(number: float) -> float:
    # Validate type
    if not isinstance(number, (int, float)) or isinstance(number, bool):
        raise TypeError("Input must be a numeric type (int or float).")
    # Validate positive
    if number < 0:
        raise ValueError("Input must be non-negative.")
    # Validate finite
    if number != number:  # NaN
        raise ValueError("Input must be a finite number.")
    if number == float('inf') or number == float('-inf'):
        raise ValueError("Input must be a finite number.")

def max_product(num_str: str, N: int, K: int) -> int:
    """
    Return the maximum product obtainable by inserting K multiplication signs into the
    number string `num_str` of length N. Each multiplication sign splits the string
    into contiguous parts; the product is the product of the integer values of those parts.
    Leading zeros in a part are allowed and are interpreted normally by int().
    """
    # Basic validation
    if not isinstance(num_str, str):
        raise TypeError("num_str must be a string")
    if len(num_str) != N:
        raise ValueError("Length of num_str does not match N")
    if N <= 0:
        raise ValueError("N must be positive")
    if K < 0:
        raise ValueError("K must be non‑negative")

    # If no multiplications, return the integer value of the whole string
    if K == 0:
        return int(num_str)

    # At most N-1 multiplications can be inserted
    K = min(K, N - 1)

    # Pre‑compute integer values of all substrings num_str[i:j] (0 <= i < j <= N)
    val = [[0] * (N + 1) for _ in range(N)]
    for i in range(N):
        num = 0
        for j in range(i + 1, N + 1):
            num = num * 10 + int(num_str[j - 1])
            val[i][j] = num

    # dp[i][k] = maximum product for the first i digits with k multiplications
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    # Base case: no multiplications
    for i in range(1, N + 1):
        dp[i][0] = val[0][i]

    # Fill DP table
    for k in range(1, K + 1):
        # Need at least k+1 digits to place k multiplications
        for i in range(k + 1, N + 1):
            best = 0
            # Split point j: last part is num_str[j:i]
            for j in range(k, i):
                prod = dp[j][k - 1] * val[j][i]
                if prod > best:
                    best = prod
            dp[i][k] = best

    return dp[N][K]

def polynomial_to_string(n: int, coeffs: list[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.

    Raises:
        ValueError: If n is negative or the length of coeffs does not match n+1.
        TypeError: If any element in coeffs is not an integer.
    """
    # Basic validation
    if not isinstance(n, int):
        raise TypeError(f"n must be an integer, got {type(n).__name__}")
    if n < 0:
        raise ValueError(f"n must be non‑negative, got {n}")
    if not isinstance(coeffs, list):
        raise TypeError(f"coeffs must be a list, got {type(coeffs).__name__}")
    if len(coeffs) != n + 1:
        raise ValueError(f"coeffs length {len(coeffs)} does not match expected {n + 1}")
    for idx, c in enumerate(coeffs):
        if not isinstance(c, int):
            raise TypeError(f"coeffs[{idx}] is not an integer: {c!r}")

    terms = []
    first_term = True

    for degree, coeff in enumerate(range(n, -1, -1)):
        c = coeffs[n - degree]  # coeffs indexed from highest degree
        if c == 0:
            continue

        # Determine sign
        if first_term:
            sign = '-' if c < 0 else ''
        else:
            sign = '-' if c < 0 else '+'

        abs_c = abs(c)

        # Determine variable part
        if degree == 0:
            var = ''
        elif degree == 1:
            var = 'x'
        else:
            var = f'x^{degree}'

        # Determine coefficient part
        if abs_c == 1 and degree > 0:
            coeff_part = ''
        else:
            coeff_part = str(abs_c)

        term = f"{sign}{coeff_part}{var}"
        terms.append(term)
        first_term = False

    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Basic type checks
    if not isinstance(encoded, str) or not isinstance(original, str) or not isinstance(message, str):
        return "Failed"

    # Lengths must match to build a consistent mapping
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e_char, o_char in zip(encoded, original):
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"  # Contradiction
        else:
            mapping[e_char] = o_char

    # Ensure the mapping covers all 26 letters and is bijective
    if len(mapping) != 26:
        return "Failed"
    if len(set(mapping.values())) != 26:
        return "Failed"

