    if k <= 0:
        return 1 if n == 0 else 0
    if n < k * x:
        return 0
    m = n - k * x
    if m < 0:
        return 0
    max_part = min(k, m)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to a maximum of 10 steps. Returns the minimum number of steps
    required to transform A into B, or "NO ANSWER!" if impossible within 10 steps.
    """
    # Basic input validation
    if not isinstance(A, str) or not isinstance(B, str):
        raise TypeError("A and B must be strings.")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list of tuples.")
    for rule in rules:
        if not (isinstance(rule, tuple) and len(rule) == 2):
            raise ValueError("Each rule must be a tuple of two strings.")
        if not isinstance(rule[0], str) or not isinstance(rule[1], str):
            raise ValueError("Rule elements must be strings.")
        if rule[0] == "":
            # Empty source would cause infinite replacements; skip such rules
            continue

    from collections import deque

    # If already equal
    if A == B:
        return 0

    max_depth = 10
    visited = {A}
    queue = deque([(A, 0)])

    while queue:
        current, depth = queue.popleft()
        if depth >= max_depth:
            continue
        next_depth = depth + 1
        for src, tgt in rules:
            if src == "":
                continue
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return next_depth
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, next_depth))
                start = idx + 1  # allow overlapping matches
    return "NO ANSWER!"

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    try:
        # Basic type checks
        if not isinstance(scenario, str) or not isinstance(liar_count, set) or not isinstance(statements, dict) or not isinstance(days_of_week, set):
            return False

        # Preprocess days of week for quick lookup
        days_upper = {day.upper() for day in days_of_week}

        for speaker, stmts in statements.items():
            # Ensure speaker is a string and stmts is iterable
            if not isinstance(speaker, str) or not hasattr(stmts, "__iter__"):
                return False

            is_liar = speaker in liar_count

            for stmt in stmts:
                if not isinstance(stmt, str):
                    return False

                stmt_upper = stmt.upper()

                # Ignore statements that mention a day of the week
                if any(day in stmt_upper for day in days_upper):
                    continue

                # Determine if statement is about guilt
                if "NOT GUILTY" in stmt_upper:
                    negated = True
                elif "GUILTY" in stmt_upper:
                    negated = False
                else:
                    # Not a guilt-related statement; ignore
                    continue

                # Identify subject of the statement
                # Strip leading/trailing whitespace and punctuation
                stripped = stmt.strip().strip(".,!?")
                tokens = stripped.split()
                if not tokens:
                    continue

                first_token = tokens[0].strip(".,!?")

                if first_token.upper() == "I":
                    subject = speaker
                else:
                    subject = first_token

                # Evaluate truth value of the statement
                if negated:
                    truth_value = (scenario != subject)
                else:
                    truth_value = (scenario == subject)

                # Check consistency with liar status
                if is_liar and truth_value:
                    return False
                if not is_liar and not truth_value:
                    return False

        return True
    except Exception:
        # Any unexpected error results in an inconsistent scenario
        return False

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    # Input validation
    if not isinstance(heights, list):
        raise TypeError("heights must be a list")
    for h in heights:
        if not isinstance(h, int):
            raise TypeError("all elements in heights must be integers")

    n = len(heights)
    if n <= 1:
        return 0

    # Longest increasing subsequence lengths ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest decreasing subsequence lengths starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic
